const item = $input.item.json;
const packages = item.packages || []; // from demand API: [{ packageId, packageName, bookingsLast7Days, bookingsLast30Days, capacityRemaining, totalCapacity, departureDate, basePriceUSD, targetMarginPct }]
const competitors = item.competitors || []; // from competitor API: [{ packageId, competitorAvgPriceUSD, competitorMinPriceUSD, competitorCount }]

const competitorByPackage = {};
competitors.forEach(c => { competitorByPackage[c.packageId] = c; });

const today = new Date();

const results = packages.map(p => {
  const departureDate = new Date(p.departureDate);
  const daysToDeparture = Math.max(0, Math.round((departureDate - today) / (1000 * 60 * 60 * 24)));

  const totalCapacity = p.totalCapacity || 0;
  const capacityRemaining = p.capacityRemaining || 0;
  const bookedCapacity = totalCapacity - capacityRemaining;
  const occupancyRate = totalCapacity > 0 ? Math.round((bookedCapacity / totalCapacity) * 100) : 0;

  const bookingVelocity = p.bookingsLast7Days || 0;
  const demandScore = Math.min(100, Math.round((bookingVelocity * 10) + (occupancyRate * 0.5)));

  // Seasonality / urgency curve based on days-to-departure and current occupancy
  let seasonalityFactor = 0;
  if (daysToDeparture <= 14) {
    seasonalityFactor = occupancyRate >= 80 ? 8 : -10;
  } else if (daysToDeparture <= 45) {
    seasonalityFactor = occupancyRate >= 70 ? 5 : -4;
  } else {
    seasonalityFactor = occupancyRate >= 60 ? 3 : 0;
  }

  const competitor = competitorByPackage[p.packageId] || null;
  const competitorAvgPriceUSD = competitor ? competitor.competitorAvgPriceUSD : null;
  const competitorPriceIndex = (competitorAvgPriceUSD && p.basePriceUSD)
    ? Math.round(((p.basePriceUSD - competitorAvgPriceUSD) / competitorAvgPriceUSD) * 1000) / 10
    : null; // positive = priced above market, negative = priced below market

  let competitorAdjustmentPct = 0;
  if (competitorPriceIndex !== null) {
    if (competitorPriceIndex > 8) competitorAdjustmentPct = -5;
    else if (competitorPriceIndex < -8) competitorAdjustmentPct = 4;
  }

  const totalAdjustmentPct = Math.round((seasonalityFactor + competitorAdjustmentPct + (demandScore - 50) * 0.1) * 10) / 10;
  const recommendedPriceUSD = p.basePriceUSD ? Math.round(p.basePriceUSD * (1 + totalAdjustmentPct / 100) * 100) / 100 : null;
  const needsReprice = Math.abs(totalAdjustmentPct) >= 3;

  return {
    packageId: p.packageId || '',
    packageName: p.packageName || '',
    departureDate: p.departureDate || '',
    daysToDeparture,
    totalCapacity,
    capacityRemaining,
    occupancyRate,
    bookingsLast7Days: p.bookingsLast7Days || 0,
    bookingsLast30Days: p.bookingsLast30Days || 0,
    basePriceUSD: p.basePriceUSD || 0,
    targetMarginPct: p.targetMarginPct || 0,
    demandScore,
    seasonalityFactor,
    competitorAvgPriceUSD,
    competitorPriceIndex,
    competitorAdjustmentPct,
    totalAdjustmentPct,
    recommendedPriceUSD,
    needsReprice
  };
});

return { json: { results, checkedAt: new Date().toISOString() } };

const item = $input.item.json;
let parsed = {};
try {
  const rawText = item.output || item.text || item.response || '{}';
  const clean = rawText.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = {
    finalPriceUSD: item.recommendedPriceUSD,
    priceChangePct: item.totalAdjustmentPct,
    reasoning: `Auto-adjusted from demand score ${item.demandScore}, seasonality ${item.seasonalityFactor}%, competitor index ${item.competitorPriceIndex}%.`,
    confidence: 'Medium'
  };
}
return {
  json: {
    ...item,
    ...parsed
  }
};

const item = $input.item.json;
const repricedAt = new Date().toISOString();

const finalPriceUSD = (item.finalPriceUSD !== undefined && item.finalPriceUSD !== null) ? item.finalPriceUSD : item.recommendedPriceUSD;
const priceChangePct = (item.priceChangePct !== undefined && item.priceChangePct !== null) ? item.priceChangePct : item.totalAdjustmentPct;

return {
  json: {
    ...item,
    finalPriceUSD,
    priceChangePct,
    repricedAt,
    repricingLogRow: [
      repricedAt,
      item.packageId || '',
      item.packageName || '',
      item.basePriceUSD || 0,
      finalPriceUSD,
      priceChangePct,
      item.demandScore || 0,
      item.seasonalityFactor || 0,
      item.competitorAdjustmentPct || 0,
      item.confidence || '',
      item.reasoning || ''
    ]
  }
};

